// MediaScreen.js - экран для работы с мультимедиа
import React, { useState, useRef } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  Image,
  Alert 
} from 'react-native';
import { Audio } from 'expo-av';
import * as ImagePicker from 'expo-image-picker';
import { Ionicons } from '@expo/vector-icons';

const MediaScreen = () => {
  const [sound, setSound] = useState();
  const [recording, setRecording] = useState();
  const [recordedURI, setRecordedURI] = useState();
  const [image, setImage] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // 💡 URL для звуковых эффектов
  const BEEP_SOUND_URI = 'https://www.soundjay.com/button/beep-07.wav'; 
  const RECORD_SUCCESS_SOUND_URI = 'https://www.soundjay.com/misc/success.wav'; 

  const soundRef = useRef();

  // Воспроизведение тестового аудио
  const playSound = async () => {
    if (isPlaying) {
      soundRef.current.stopAsync();
      setIsPlaying(false);
      return;
    }

    try {
      const { sound } = await Audio.Sound.createAsync(
        { uri: BEEP_SOUND_URI }
      );
      soundRef.current = sound;
      await sound.playAsync();
      setIsPlaying(true);

      sound.setOnPlaybackStatusUpdate((status) => {
        if (status.didJustFinish) {
          setIsPlaying(false);
          sound.unloadAsync();
        }
      });
    } catch (error) {
      Alert.alert('Ошибка', 'Не удалось воспроизвести аудио');
    }
  };

  // Запись аудио
  const startRecording = async () => {
    try {
      // Запрос разрешения на микрофон
      const { status: micStatus } = await Audio.requestPermissionsAsync();
      if (micStatus !== 'granted') {
        Alert.alert('Разрешение необходимо', 'Для записи аудио необходимо разрешение на микрофон.');
        return;
      }

      await Audio.setAudioModeAsync({
        allowsRecordingIOS: true,
        playsInSilentModeIOS: true,
      });

      const { recording } = await Audio.Recording.createAsync(
        Audio.RecordingOptionsPresets.HIGH_QUALITY
      );
      setRecording(recording);
      Alert.alert('Запись начата', 'Говорите в микрофон...');

    } catch (error) {
      console.error('Ошибка старта записи:', error);
      Alert.alert('Ошибка', 'Не удалось начать запись');
    }
  };

  // Остановка записи
  const stopRecording = async () => {
    try {
      if (recording) {
        await recording.stopAndUnloadAsync();
        const uri = recording.getURI();
        setRecordedURI(uri);
        setRecording(undefined);

        // 💡 Воспроизводим звук успеха
        const { sound } = await Audio.Sound.createAsync({ uri: RECORD_SUCCESS_SOUND_URI });
        await sound.playAsync();
        sound.unloadAsync(); 

        Alert.alert('Запись завершена', `Аудио сохранено по URI: ${uri}`);
      }
    } catch (error) {
      console.error('Ошибка остановки записи:', error);
      Alert.alert('Ошибка', 'Не удалось остановить запись');
    }
  };

  // Воспроизведение записанного аудио
  const playRecordedAudio = async () => {
    if (!recordedURI) {
      Alert.alert('Ошибка', 'Аудиозапись не найдена. Сначала запишите ее.');
      return;
    }

    try {
      const { sound } = await Audio.Sound.createAsync({ uri: recordedURI });
      await sound.playAsync();
      sound.setOnPlaybackStatusUpdate((status) => {
        if (status.didJustFinish) {
          sound.unloadAsync();
        }
      });
    } catch (error) {
      Alert.alert('Ошибка', 'Не удалось воспроизвести записанное аудио');
    }
  };

  // Выбор изображения
  const pickImage = async (useCamera = false) => {
    let result;

    if (useCamera) {
      const { status } = await ImagePicker.requestCameraPermissionsAsync();
      if (status !== 'granted') {
        Alert.alert('Разрешение необходимо', 'Для использования камеры необходимо разрешение.');
        return;
      }
      result = await ImagePicker.launchCameraAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        allowsEditing: true,
        // ✅ Установка соотношения 9:16
        aspect: [9, 16],
        quality: 1,
      });
    } else {
      const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (status !== 'granted') {
        Alert.alert('Разрешение необходимо', 'Для доступа к галерее необходимо разрешение.');
        return;
      }
      result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        allowsEditing: true,
        // ✅ Установка соотношения 9:16
        aspect: [9, 16],
        quality: 1,
      });
    }

    if (!result.canceled) {
      setImage(result.assets[0].uri);
    } else {
      setImage(null);
    }
  };

  // Компонент кнопки
  const Button = ({ title, onPress, icon, color, disabled = false }) => (
    <TouchableOpacity 
      style={[styles.button, { backgroundColor: color }, disabled && styles.disabledButton]} 
      onPress={onPress}
      disabled={disabled}
    >
      <Ionicons name={icon} size={20} color="white" />
      <Text style={styles.buttonText}>{title}</Text>
    </TouchableOpacity>
  );

  return (
    <ScrollView style={styles.container}>

      {/* 💡 НОВОЕ ОСМЫСЛЕННОЕ ОПИСАНИЕ */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Цель модуля "Мультимедиа"</Text>
        <Text style={styles.description}>
          Этот модуль демонстрирует взаимодействие приложения с нативными функциями устройства. Используйте его для проверки доступа к камере, галерее и микрофону, а также корректной работы Expo API.
        </Text>
      </View>

      {/* Секция Изображений */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Изображения (9:16)</Text>
        <View style={styles.buttonRow}>
          <Button 
            title="Камера" 
            onPress={() => pickImage(true)} 
            icon="camera" 
            color="#34C759"
          />
          <Button 
            title="Галерея" 
            onPress={() => pickImage(false)} 
            icon="images" 
            color="#007AFF"
          />
        </View>

        {image && (
          <View style={styles.imagePreviewContainer}>
            <Image source={{ uri: image }} style={styles.imagePreview} />
            <Text style={styles.imageInfo}>Соотношение 9:16 (вертикальное)</Text>
          </View>
        )}
      </View>

      {/* Секция Аудио */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Аудио и Звук</Text>
        <View style={styles.buttonRow}>
          <Button 
            title={recording ? "Идет запись..." : "Записать аудио"} 
            onPress={recording ? stopRecording : startRecording} 
            icon={recording ? "square" : "mic"} 
            color={recording ? "#FF3B30" : "#FF9500"}
          />
        </View>

        <View style={[styles.buttonRow, { marginTop: 10 }]}>
          <Button 
            title={isPlaying ? "Стоп Звук" : "Тестовый Звук"} 
            onPress={playSound} 
            icon={isPlaying ? "volume-high" : "volume-medium"} 
            color={isPlaying ? "#8E8E93" : "#5856D6"}
          />
          <Button 
            title="Воспроизвести запись" 
            onPress={playRecordedAudio} 
            icon="play" 
            color="#34C759"
            disabled={!recordedURI}
          />
        </View>

        {recordedURI && (
          <Text style={styles.audioInfo}>
            Записанное аудио готово к воспроизведению.
          </Text>
        )}
      </View>

    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
    padding: 10,
  },
  section: {
    backgroundColor: 'white',
    padding: 15,
    borderRadius: 12,
    marginBottom: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 15,
    color: '#333',
  },
  description: {
    fontSize: 14,
    color: '#666',
    marginBottom: 15,
  },
  buttonRow: {
